"""Shared bounded FIFO. The Store record is the only authoritative state."""

class Queue:
    def __init__(self, store, capacity=2):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self._store = store
        while True:
            version, record = store.load()
            if record is not None:
                if record['capacity'] != capacity:
                    raise ValueError("all queues sharing a Store must use its capacity")
                break
            record = {'capacity': capacity, 'items': [], 'puts': {}, 'takes': {}}
            if store.compare_swap(version, record):
                break

    def put(self, request_id, item: int) -> bool:
        while True:
            version, record = self._store.load()
            if request_id in record['puts']:
                old_item, accepted = record['puts'][request_id]
                if old_item != item:
                    raise ValueError("put request ID reused with a different item")
                return accepted
            accepted = len(record['items']) < record['capacity']
            if accepted:
                record['items'].append(item)
            record['puts'][request_id] = (item, accepted)
            # Rejections also commit a memo. A loser reloads all current state.
            if self._store.compare_swap(version, record):
                return accepted

    def take(self, request_id) -> int | None:
        while True:
            version, record = self._store.load()
            if request_id in record['takes']:
                return record['takes'][request_id]
            result = record['items'].pop(0) if record['items'] else None
            record['takes'][request_id] = result
            if self._store.compare_swap(version, record):
                return result

    def snapshot(self) -> list[int]:
        _, record = self._store.load()
        return record['items']
EOF

